function emdo_mc3_cat($name,$slug,$en_name,$en_slug){
  $t=get_term_by('slug',$slug,'category');
  if(!$t instanceof WP_Term){$r=wp_insert_term($name,'category',array('slug'=>$slug));if(is_wp_error($r))throw new RuntimeException($r->get_error_message());$t=get_term((int)$r['term_id'],'category');}
