}
function emdo_mc3_words($html){$plain=trim(preg_replace('/\s+/u',' ',wp_strip_all_tags(strip_shortcodes($html))));if($plain==='')return 0;preg_match_all("/[\\p{L}\\p{M}]+(?:[’'’-][\\p{L}\\p{M}]+)*/u",$plain,$m);return count($m[0]);}
function emdo_mc3_post_id($key,$slug){$ids=get_posts(array('post_type'=>'post','post_status'=>array('publish','draft','pending','future','private'),'posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_emdo_authority_key','meta_value'=>$key));if($ids)return (int)$ids[0];$p=get_page_by_path($slug,OBJECT,'post');return $p instanceof WP_Post?(int)$p->ID:0;}
function emdo_mc3_image($post_id,$img){
