  update_post_meta($aid,'_wp_attachment_image_alt',(string)$img['alt_es']);update_post_meta($aid,'_en_US_attachment_alt',(string)$img['alt_en']);set_post_thumbnail($post_id,$aid);return $aid;
}
function emdo_mc3_meat_slug(){foreach(array('carnes','carne') as $s){$t=get_term_by('slug',$s,'product_cat');if($t instanceof WP_Term)return $t->slug;}foreach(array('Carnes','Carne') as $n){$t=get_term_by('name',$n,'product_cat');if($t instanceof WP_Term)return $t->slug;}throw new RuntimeException('Meat product category not found');}
$dir=(string)getenv('EMDO_MC3_DIR');if($dir===''||!is_dir($dir))throw new RuntimeException('EMDO_MC3_DIR missing');$only=(string)getenv('EMDO_MC3_ONLY_FILE');if($only!==''){$f=trailingslashit($dir).basename($only);if(!is_file($f))throw new RuntimeException('Article file not found: '.$only);$files=array($f);}else{$files=glob(trailingslashit($dir).'*.php');sort($files,SORT_NATURAL);}
$guide=emdo_mc3_cat('Guías y consejos','guias-y-consejos','Guides and advice','guides-and-advice');$meat=emdo_mc3_cat('Carnes','carnes','Beef and meat','beef-and-meat');$product_slug=emdo_mc3_meat_slug();$report=array('release'=>'meat-cluster-3-20260826','posts'=>array());
