e_post_meta($post_id,'_en_US_seo_title',$a['en_seo_title']);update_post_meta($post_id,'_en_US_seo_description',$a['en_seo_desc']);if(defined('WPSEO_VERSION')||metadata_exists('post',$post_id,'_yoast_wpseo_metadesc')){update_post_meta($post_id,'_yoast_wpseo_title',$a['seo_title']);update_post_meta($post_id,'_yoast_wpseo_metadesc',$a['seo_desc']);}if(defined('RANK_MATH_VERSION')||metadata_exists('post',$post_id,'rank_math_description')){update_post_meta($post_id,'rank_math_title',$a['seo_title']);update_post_meta($post_id,'rank_math_description',$a['seo_desc']);}$aid=emdo_mc3_image($post_id,$a['image']);$meta=wp_get_attachment_metadata($aid);$w=(int)($meta['width']??0);$h=(int)($meta['height']??0);if($w<1200||$h<700)throw new RuntimeException($a['key'].': image too small '.$w.'x'.$h);$we=emdo_mc3_words($content);$wn=emdo_mc3_words($en_content);if($we<900||$wn<800)throw new RuntimeException($a['key'].': article too short ES='.$we.' EN='.$wn);$report['posts'][]=array('key'=>$a['key'],'id'=>$post_id,'status'=>get_post_status($post_id),'slug'=>(string)get_post_field('post_name',$post_id),'en_slug'=>sanitize_title($a['en_slug']),'words_es'=>$we,'words_en'=>$wn,'image_id'=>$aid,'image_w'=>$w,'image_h'=>$h,'image_source'=>$a['image']['source'],'image_page'=>$a['image']['page']);}
